/* Minimal orchestration controller (pseudo) */
async function orchestrateSaga(steps) {
  const sagaId = generateId();
  const completed = [];
  try {
    for (const step of steps) {
      await step.action({sagaId});
      completed.push(step);
    }
    return {status: 'completed', sagaId};
  } catch (err) {
    // compensate in reverse
    for (const step of completed.reverse()) {
      try { await step.compensate({sagaId}); } catch (e) { log('comp fail', e); }
    }
    return {status: 'failed', sagaId, error: err.message};
  }
}
